try {
const f = $input.first().json.files || [];
if (!f.length) throw new Error('Arquivo nexxusdoc_frete_n8n.json nao encontrado em Sua Area > Nexxus > NexxusDoc.');
return [{ json: { id: f[0].id } }];
} catch (erro) {
  const m = erro && erro.message ? erro.message : (typeof erro === 'string' ? erro : JSON.stringify(erro));
  throw new Error('[Frete: escolher estado] ' + m + (erro && erro.stack ? ' | ' + String(erro.stack).split('\n').slice(0, 4).join(' / ') : ''));
}

try {

const est = $('Frete: baixar estado').first().json || {};
const threads = ($input.first().json.threads || []).map(t => t.id).filter(Boolean);
const conhecidas = {};
for (const [mid, f] of Object.entries(est.faturas || {})) conhecidas[f.conversa || mid] = f;
const aprov = est.aprovacoes || {};
const limite = Date.now() - 30 * 864e5;
const abrir = threads.filter(t => {
  const f = conhecidas[t];
  if (!f) return true;
  if (aprov[t]) return false;
  return Date.parse(f.recebido_em || 0) > limite;
}).slice(0, 40);
return abrir.length ? abrir.map(id => ({json: {threadId: id}})) : [{json: {dummy: true, _conversas: threads.length}}];

} catch (erro) {
  const m = erro && erro.message ? erro.message : (typeof erro === 'string' ? erro : JSON.stringify(erro));
  throw new Error('[Frete: fila de conversas] ' + m + (erro && erro.stack ? ' | ' + String(erro.stack).split('\n').slice(0, 4).join(' / ') : ''));
}

try {

const est = $('Frete: baixar estado').first().json || {};
const ja = est.faturas || {};
const agora = new Date().toISOString().slice(0, 19) + 'Z';
const hdr = (m, n) => (((m.payload || {}).headers || []).find(h => String(h.name).toLowerCase() === n) || {}).value || '';
const partes = p => { const out = []; const anda = x => { if (!x) return; if (x.filename) out.push(x); (x.parts || []).forEach(anda); }; anda(p); return out; };
const downloads = [], aprovacoes = {};
let lidas = 0;
for (const it of $input.all()) {
  const t = it.json || {};
  if (!t.id || !Array.isArray(t.messages)) continue;
  lidas++;
  let fatura = null;
  for (const m of t.messages) {
    const de = hdr(m, 'from').toLowerCase();
    const agente = /br-asgroup\.com/.test(de) ? 'asia' : /dmslog\.com/.test(de) ? 'dms' : '';
    if (agente && !fatura) {
      const pdf = partes(m.payload).find(x => agente === 'asia' ? /^AR INV/i.test(x.filename) : /^ND_.*\.pdf$/i.test(x.filename));
      if (pdf && pdf.body && pdf.body.attachmentId) fatura = {mid: m.id, agente, anexo: pdf.filename, att: pdf.body.attachmentId,
        recebido_em: new Date(Number(m.internalDate)).toISOString().slice(0, 19) + 'Z', assunto: hdr(m, 'subject').slice(0, 250)};
      continue;
    }
    // aprovacao: resposta de alguem do Grupo SBF dizendo "aprovada" (sem "nao aprovada"/"reprovada")
    if (fatura && /@(partner\.)?gruposbf\.com\.br/.test(de) && /\baprovad[ao]s?\b/i.test(m.snippet || '') && !/(n[aã]o|reprovad)\s*aprovad|reprovad/i.test(m.snippet || '')) {
      const email = (de.match(/[a-z0-9._%+-]+@(partner\.)?gruposbf\.com\.br/) || [''])[0];
      if (!aprovacoes[t.id]) aprovacoes[t.id] = {por: email, em: new Date(Number(m.internalDate)).toISOString().slice(0, 19) + 'Z', mensagem: m.id,
        trecho: String(m.snippet || '').split(/\bAtt\b|Em (seg|ter|qua|qui|sex|s[aá]b|dom)\./)[0].trim().slice(0, 160)};
    }
  }
  if (fatura && !ja[fatura.mid]) downloads.push({...fatura, conversa: t.id, nome: fatura.mid + '_' + fatura.anexo.replace(/[\\/:*?"<>|]/g, '_')});
}
const out = downloads.length ? downloads.map(d => ({json: {...d}})) : [{json: {dummy: true}}];
out[0].json._aprovacoes = JSON.parse(JSON.stringify(aprovacoes));
out[0].json._lidas = lidas;
out[0].json._agora = agora;
return out;

} catch (erro) {
  const m = erro && erro.message ? erro.message : (typeof erro === 'string' ? erro : JSON.stringify(erro));
  throw new Error('[Frete: analisar conversas] ' + m + (erro && erro.stack ? ' | ' + String(erro.stack).split('\n').slice(0, 4).join(' / ') : ''));
}

try {

const metas = $('Frete: analisar conversas').all();
return $input.all().map((it, i) => {
  const m = {...metas[i].json};
  delete m._aprovacoes; delete m._lidas; delete m._agora;
  const b64 = String((it.json || {}).data || '').replace(/-/g, '+').replace(/_/g, '/');
  return {json: {...m, ok: b64.length > 100}, binary: {data: {data: b64, mimeType: 'application/pdf', fileName: m.nome}}};
});

} catch (erro) {
  const m = erro && erro.message ? erro.message : (typeof erro === 'string' ? erro : JSON.stringify(erro));
  throw new Error('[Frete: preparar PDF] ' + m + (erro && erro.stack ? ' | ' + String(erro.stack).split('\n').slice(0, 4).join(' / ') : ''));
}

try {

const estado = JSON.parse(JSON.stringify($('Frete: baixar estado').first().json || {}));
const seguro = n => { try { return $(n).all(); } catch (e) { return []; } };
const an = seguro('Frete: analisar conversas');
const ctrl = ((an[0] || {}).json) || {};
const pdfs = seguro('Frete: preparar PDF'), subidos = seguro('Frete: enviar ao Drive');
const agora = ctrl._agora || (new Date().toISOString().slice(0, 19) + 'Z');
estado.faturas = estado.faturas || {};
estado.aprovacoes = estado.aprovacoes || {};
let novas = 0, erros = 0;
const exemplos = [];
pdfs.forEach((it, i) => {
  const m = it.json || {}, up = (subidos[i] || {}).json || {};
  if (!m.mid) return;
  if (!m.ok || !up.id) { erros++; exemplos.push({anexo: m.anexo, erro: !m.ok ? 'anexo vazio' : 'não subiu ao Drive'}); return; }
  estado.faturas[m.mid] = {agente: m.agente, conversa: m.conversa, recebido_em: m.recebido_em, assunto: m.assunto, anexo: m.anexo,
    arquivo: m.nome, drive_id: up.id, lido_em: agora};
  novas++;
});
let aprov = 0;
for (const [t, a] of Object.entries(ctrl._aprovacoes || {})) { if (!estado.aprovacoes[t]) { estado.aprovacoes[t] = {...a}; aprov++; } }
estado.versao = 1;
estado.ultima_execucao = agora;
estado.ultima_rodada = {em: agora, conversas: ctrl._lidas || 0, novas, aprovacoes: aprov, erros, erros_exemplo: exemplos.slice(0, 5)};
return [{json: {id: $('Frete: escolher estado').first().json.id, conteudo: JSON.stringify(estado)}}];

} catch (erro) {
  const m = erro && erro.message ? erro.message : (typeof erro === 'string' ? erro : JSON.stringify(erro));
  throw new Error('[Frete: montar estado] ' + m + (erro && erro.stack ? ' | ' + String(erro.stack).split('\n').slice(0, 4).join(' / ') : ''));
}
